    25  static void
    26  compute_directory_size (blksize_t block_size,
    27                          int *ret_dir_size, int *ret_dir_bits)
    28  {
    29    /* Create the initial hash table directory.  */
    30    int dir_size = 8 * sizeof (off_t);
    31    int dir_bits = 3;
    32
    33    if (block_size > INT_MAX / 2)
    34      block_size = INT_MAX / 2;
    35    while (dir_size < block_size && dir_bits < GDBM_HASH_BITS - 3)
    36      {
    37        dir_size <<= 1;
    38        dir_bits++;
    39      }
    40
    41    *ret_dir_size = dir_size;
    42    *ret_dir_bits = dir_bits;
    43  }
