   121  static int
   122  validate_header_numsync (gdbm_file_header const *hdr, struct stat const *st)
   123  {
   124    int result = GDBM_NO_ERROR;
   125    int dir_size, dir_bits;
   126
   127    if (!(hdr->block_size > 0
   128          && hdr->block_size > (sizeof (gdbm_file_header) + sizeof (gdbm_ext_header))
   129          && hdr->block_size - (sizeof (gdbm_file_header) + sizeof (gdbm_ext_header)) >=
   130          sizeof(avail_block)))
   131      {
   132        return GDBM_BLOCK_SIZE_ERROR;
   133      }
   134
   135    /* Technically speaking, the condition below should read
   136           hdr->next_block != st->st_size
   137       However, gdbm versions prior to commit 4e819c98 could leave
   138       hdr->next_block pointing beyond current end of file. To ensure
   139       backward compatibility with these versions, the condition has been
   140       slackened to this: */
   141    if (hdr->next_block < st->st_size)
   142      result = GDBM_NEED_RECOVERY;
   143
   144    /* Make sure dir and dir + dir_size fall within the file boundary */
   145    if (!(hdr->dir > 0
   146          && hdr->dir < st->st_size
   147          && hdr->dir_size > 0
   148          && hdr->dir + hdr->dir_size < st->st_size))
   149      return GDBM_BAD_HEADER;
   150
   151    compute_directory_size (hdr->block_size, &dir_size, &dir_bits);
   152    if (!(hdr->dir_size >= dir_size))
   153      return GDBM_BAD_HEADER;
   154    compute_directory_size (hdr->dir_size, &dir_size, &dir_bits);
   155    if (hdr->dir_bits != dir_bits)
   156      return GDBM_BAD_HEADER;
   157
   158    if (!(hdr->bucket_size > 0 && hdr->bucket_size > sizeof (hash_bucket)))
   159      return GDBM_BAD_HEADER;
   160
   161    if (hdr->bucket_elems != bucket_element_count (hdr->bucket_size))
   162      return GDBM_BAD_HEADER;
   163
   164    return result;
   165  }
