   167  static int
   168  validate_header (gdbm_file_header const *hdr, struct stat const *st)
   169  {
   170    /* Is the magic number good? */
   171    switch (hdr->header_magic)
   172      {
   173      case GDBM_OMAGIC:
   174      case GDBM_MAGIC:
   175        return validate_header_std (hdr, st);
   176
   177      case GDBM_NUMSYNC_MAGIC:
   178        return validate_header_numsync (hdr, st);
   179
   180      default:
   181        switch (hdr->header_magic)
   182          {
   183          case GDBM_OMAGIC_SWAP:
   184          case GDBM_MAGIC32_SWAP:
   185          case GDBM_MAGIC64_SWAP:
   186          case GDBM_NUMSYNC_MAGIC32_SWAP:
   187          case GDBM_NUMSYNC_MAGIC64_SWAP:
   188            return GDBM_BYTE_SWAPPED;
   189
   190          case GDBM_MAGIC32:
   191          case GDBM_MAGIC64:
   192          case GDBM_NUMSYNC_MAGIC32:
   193          case GDBM_NUMSYNC_MAGIC64:
   194            return GDBM_BAD_FILE_OFFSET;
   195
   196          default:
   197            return GDBM_BAD_MAGIC_NUMBER;
   198          }
   199      }
   200  }
