   202  int
   203  _gdbm_validate_header (GDBM_FILE dbf)
   204  {
   205    struct stat file_stat;
   206    int rc;
   207
   208    if (fstat (dbf->desc, &file_stat))
   209      return GDBM_FILE_STAT_ERROR;
   210
   211    rc = validate_header (dbf->header, &file_stat);
   212    if (rc == 0)
   213      {
   214        if (gdbm_avail_block_validate (dbf, dbf->avail, dbf->avail_size))
   215          rc = GDBM_BAD_AVAIL;
   216      }
   217    return rc;
   218  }
