   220  /* Do we have ftruncate? */
   221  static inline int
   222  _gdbm_ftruncate (GDBM_FILE dbf)
   223  {
   224  #if HAVE_FTRUNCATE
   225    return ftruncate (dbf->desc, 0);
   226  #else
   227    int fd;
   228    fd = open (dbf->name, O_RDWR|O_TRUNC, mode);
   229    if (fd == -1)
   230      return -1;
   231    return close (fd);
   232  #endif
   233  }
